def has_short_cycle(G, max_girth=5):
    """Check if graph has any cycle of length <= max_girth"""
    for v in G.nodes():
        # BFS from v, check if we find a cycle of length <= max_girth
        dist = {v: 0}
        queue = [v]
        while queue:
            u = queue.pop(0)
            if dist[u] >= max_girth - 1:
                continue
            for w in G.neighbors(u):
                if w not in dist:
                    dist[w] = dist[u] + 1
                    queue.append(w)
                elif dist[w] >= dist[u]:  # found a cycle
                    cycle_len = dist[u] + dist[w] + 1
                    if cycle_len <= max_girth:
                        return True
    return False

def check_girth_ge6(G):
    """Returns True if girth >= 6 (no cycles of length 3,4,5)"""
    # Check for triangles
    for u, v, w in combinations(G.nodes(), 3):
        if G.has_edge(u,v) and G.has_edge(v,w) and G.has_edge(u,w):
            return False
    # Check for 4-cycles
    for u in G.nodes():
        for v in G.neighbors(u):
            for w in G.neighbors(v):
                if w != u:
                    for x in G.neighbors(w):
                        if x != v and G.has_edge(x, u) and x != u:
                            return False
    # Check for 5-cycles
    for u in G.nodes():
        for v in G.neighbors(u):
            for w in G.neighbors(v):
                if w != u:
                    for x in G.neighbors(w):
                        if x != v and x != u:
                            for y in G.neighbors(x):
                                if y != w and G.has_edge(y, u) and y != v:
                                    return False
    return True

def fast_girth_check(G):
    """Fast girth check using BFS"""
    for start in G.nodes():
        # BFS tree
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        while queue:
            u = queue.pop(0)
            for v in G.neighbors(u):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif parent[u] != v:  # back edge found
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= 5:
                        return cycle_len
    return float('inf')

