# Let me construct PG(2,3) first
# Points of PG(2,3): vectors [x:y:z] over GF(3), not all zero, up to scalar
# GF(3) = {0,1,2}

def gf3_points():
    """Generate all points of PG(2,3)"""
    points = []
    for x in range(3):
        for y in range(3):
            for z in range(3):
                if x == 0 and y == 0 and z == 0:
                    continue
                # Normalize: first nonzero coordinate is 1
                if x != 0:
                    # divide by x
                    inv_x = 1 if x == 1 else 2  # 2*2=4=1 mod 3
                    pt = (1, (y*inv_x)%3, (z*inv_x)%3)
                elif y != 0:
                    inv_y = 1 if y == 1 else 2
                    pt = (0, 1, (z*inv_y)%3)
                else:
                    pt = (0, 0, 1)
                if pt not in points:
                    points.append(pt)
    return points

def dot_product(p, l):
    """Inner product mod 3"""
    return (p[0]*l[0] + p[1]*l[1] + p[2]*l[2]) % 3

