# Strategy: add 2 new vertices and connect them to existing ones
# We need to be careful about girth

def can_add_edge(adj, u, v, n):
    """Check if adding edge (u,v) would create a cycle of length <= 5"""
    # Check triangle: common neighbor
    if adj[u] & adj[v]:
        return False
    # Check C4: u and v have a common neighbor at distance 2
    # i.e., exists w,x: u-w-x-v or u-w and v-w (already checked)
    # C4: u-a-b-v-u, so a in adj[u], b in adj[v], a-b edge
    for a in adj[u]:
        if a == v:
            continue
        for b in adj[v]:
            if b == u:
                continue
            if b in adj[a]:
                return False
    # Check C5: path of length 3 between u and v (not through direct edge)
    # u-a-b-c-v
    dist_from_u = {u: 0}
    q = deque([u])
    while q:
        x = q.popleft()
        if dist_from_u[x] >= 4:
            continue
        for w in adj[x]:
            if w not in dist_from_u:
                dist_from_u[w] = dist_from_u[x] + 1
                q.append(w)
    if v in dist_from_u and dist_from_u[v] <= 3:
        return False
    return True

