def find_neighbors_for_new_vertex(adj, new_v, existing_verts, min_deg=4):
    """Find a set of neighbors for new_v from existing_verts"""
    chosen = []
    for c in existing_verts:
        if can_add_edge(adj, new_v, c, n):
            # Tentatively add
            adj[new_v].add(c)
            adj[c].add(new_v)
            chosen.append(c)
            if len(chosen) == min_deg:
                break
    return chosen

